// Tessellates a horn's STEP model (mm) into the compact mesh the 3D view draws (src/data/meshes/<id>.ts). The STEP
// file is not in the repo: give its path and the horn's catalog id (`vp run horn-mesh -- path/to/horn.step diy_os90x50`;
// LIN and ANG override the deflections and CREASE the crease angle to try others). Run it after changing the STEP file or the settings below;
// the page and the tests only ever read the generated file.
//
// The model's axes: x across the mouth's width, y up its height, z along the axis, the throat flange's back face (the
// face the driver bolts to) at z = 0 and the mouth toward +z; the model's z axis is the driver's axis. The view
// places the mesh by its origin, so an asymmetric horn keeps its throat on the driver. build/step-mesh.mjs meshes each
// face to LINEAR_DEFLECTION_MM and ANGULAR_DEFLECTION, welds the vertices on a QUANT_MM grid and splits them along the
// edges sharper than CREASE_DEG, so the view shades the flare smooth and keeps the flange's edges crisp. The script
// also reads the throat flange off the mesh (its diameter, the throat and the bolt holes at z = 0) and writes it into
// the header.
import path from "node:path";
import { sourceRows, tessellateStep, writeSource } from "./step-mesh.mjs";

const [STEP, ID] = process.argv.slice(2);
if (!STEP || !ID || !/^[a-z][a-z0-9_]*$/.test(ID))
  throw new Error(
    "give the horn's STEP file (it is not in the repo) and its catalog id (lower case, digits and _)",
  );
const OUT = new URL(`../src/data/meshes/${ID}.ts`, import.meta.url);
const NAME = `${ID.toUpperCase()}_MESH`;
/** Largest gap between the mesh and the true surface, mm. */
const LINEAR_DEFLECTION_MM = Number(process.env.LIN ?? 3);
/** Largest angle between neighboring facets on a curve, radians. */
const ANGULAR_DEFLECTION = Number(process.env.ANG ?? 0.5);
/** The weld grid and the stored unit, mm. */
const QUANT_MM = 0.5;
/**
 * Neighboring facets that meet at more than this angle keep a crisp edge between them, degrees: the flange's edges and
 * the mouth's rim are 90°, while the flare's last few mm turn up to about 60° between rows of facets at these
 * deflections, which a lower angle would draw as bands.
 */
const CREASE_DEG = Number(process.env.CREASE ?? 60);

const { meshCount, pos, idx, inTris, lo, hi } = await tessellateStep(STEP, {
  linearDeflectionMm: LINEAR_DEFLECTION_MM,
  angularDeflection: ANGULAR_DEFLECTION,
  quantMm: QUANT_MM,
  creaseDeg: CREASE_DEG,
});
if (lo[2] !== 0) throw new Error(`the throat flange's back face is at z = ${lo[2]} mm, not 0`);

// the throat flange at z = 0: its rim, the throat, and the bolt holes between them (one per quadrant)
// (each point once: a vertex split at a crease has copies)
const backKeys = new Set();
for (let i = 0; i < pos.length; i += 3)
  if (pos[i + 2] === 0) backKeys.add(`${pos[i]},${pos[i + 1]}`);
const back = [...backKeys].map((k) => k.split(",").map((v) => Number(v) * QUANT_MM));
const r = back.map(([x, y]) => Math.hypot(x, y));
const rim = Math.max(...r);
const throat = Math.min(...r);
const quadrants = new Map();
back.forEach(([x, y], i) => {
  if (r[i] < throat + 1 || r[i] > rim - 1) return;
  const q = `${Math.sign(x)},${Math.sign(y)}`;
  quadrants.set(q, [...(quadrants.get(q) ?? []), [x, y]]);
});
const holes = [...quadrants.values()].map((pts) => {
  const c = [0, 1].map((k) => pts.reduce((s, p) => s + p[k], 0) / pts.length);
  return {
    c,
    d: (2 * pts.reduce((s, p) => s + Math.hypot(p[0] - c[0], p[1] - c[1]), 0)) / pts.length,
  };
});
const mm = (v) => v.toFixed(1);
const flange =
  `throat flange ⌀${mm(2 * rim)} mm, throat ⌀${mm(2 * throat)} mm, ${holes.length} holes ` +
  `⌀${holes.map((h) => mm(h.d)).join("/")} mm on ⌀${holes.map((h) => mm(2 * Math.hypot(...h.c))).join("/")} mm`;

const src = `// Generated by build/horn-mesh.mjs from ${path.basename(STEP)} (not in the repo): do not edit by hand.
// Tessellated to ${LINEAR_DEFLECTION_MM} mm and ${ANGULAR_DEFLECTION} rad, welded on a ${QUANT_MM} mm grid and split at edges over ${CREASE_DEG}°
// (${pos.length / 3} vertices, ${idx.length / 3} triangles, from ${inTris}). Model axes, mm: x across the mouth's ${mm(hi[0] - lo[0])} mm, y up its ${mm(hi[1] - lo[1])} mm, z along the
// axis from the throat flange's back face (z = 0) to the mouth (z = ${mm(hi[2])}). From the mesh: ${flange}.
import type { PartMesh } from "../../types";

export const ${NAME}: PartMesh = {
  unitMm: ${QUANT_MM},
  min: [${lo.map((v) => +v.toFixed(2)).join(", ")}],
  max: [${hi.map((v) => +v.toFixed(2)).join(", ")}],
  positions: [
${sourceRows(pos)}
  ],
  indices: [
${sourceRows(idx)}
  ],
};
`;
writeSource(OUT, src);
console.log(
  `${meshCount} meshes, ${inTris} triangles in; ${pos.length / 3} vertices, ${idx.length / 3} triangles out; ` +
    `bounds ${lo.map(mm).join()} .. ${hi.map(mm).join()} mm; ${flange}; ${(src.length / 1024).toFixed(1)} kB`,
);
